/*
 * prog24_query_string_parser.c
 *
 * Re‑implementation of the original binary (prog24_query_string_parser).
 * The program reads one line from stdin, treats it as a URL‑encoded query
 * string, decodes each “key=value” pair and prints the pairs in the form
 *
 *      key=value
 *
 * one per line.  Empty tokens (e.g. consecutive ‘&’) are ignored.
 * If no line can be read, the program prints “NO_INPUT”.
 *
 * The implementation follows the logic discovered in the decompiled
 * binary (functions `main` and `decode`).
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_LINE 2048   /* size of the buffers used by the original binary */

static char main_line[MAX_LINE];
static char main_key[MAX_LINE];
static char main_val[MAX_LINE];

/* URL‑decode a fragment.
 *  src  – pointer to the source characters
 *  len  – number of characters to decode
 *  dst  – destination buffer (must be large enough)
 *
 * The decoder implements the same rules as the original `decode` function:
 *   '+'  → space
 *   %XX → byte with hexadecimal value XX (only when both X are hex digits)
 *   otherwise the character is copied unchanged.
 * The result is NUL‑terminated.
 */
static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, j = 0;

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dst[j++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            char hex[3] = { src[i + 1], src[i + 2], '\0' };
            dst[j++] = (char)strtol(hex, NULL, 16);
            i += 3;
        } else {
            dst[j++] = c;
            ++i;
        }
    }
    dst[j] = '\0';
}

/* Trim a trailing newline and optional carriage‑return from a string. */
static void trim_newline(char *s)
{
    size_t n = strlen(s);
    if (n == 0) return;

    if (s[n - 1] == '\n') {
        s[--n] = '\0';
    }
    if (n > 0 && s[n - 1] == '\r') {
        s[--n] = '\0';
    }
}

int main(void)
{
    /* read a line from stdin */
    if (fgets(main_line, sizeof(main_line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    trim_newline(main_line);

    /* parse the query string: tokens are separated by '&' */
    char *p = main_line;
    while (*p) {
        /* locate the end of the current token */
        char *amp = strchr(p, '&');
        size_t token_len = amp ? (size_t)(amp - p) : strlen(p);

        /* ignore empty tokens (e.g. "&&") */
        if (token_len == 0) {
            if (amp)
                p = amp + 1;
            else
                break;
            continue;
        }

        /* split token into key and optional value */
        char *eq = memchr(p, '=', token_len);
        const char *key_src;
        size_t key_len;
        const char *val_src = NULL;
        size_t val_len = 0;

        if (eq) {
            key_src = p;
            key_len = (size_t)(eq - p);
            val_src = eq + 1;
            val_len = token_len - key_len - 1;   /* may be zero */
        } else {
            key_src = p;
            key_len = token_len;
        }

        /* decode key and value */
        decode(key_src, key_len, main_key);
        if (val_len > 0) {
            decode(val_src, val_len, main_val);
        } else {
            main_val[0] = '\0';
        }

        /* output the pair */
        printf("%s=%s\n", main_key, main_val);

        /* advance to the next token */
        if (!amp)
            break;
        p = amp + 1;
    }

    return 0;
}
